import { cx } from "./cx.js";

export function Button({
  className = "",
  tone = "secondary",
  iconOnly = false,
  children,
  ...props
}) {
  return (
    <button
      {...props}
      className={cx(
        "nexus-ui-button",
        tone !== "secondary" && `nexus-ui-button--${tone}`,
        iconOnly && "nexus-ui-button--icon",
        className,
      )}
    >
      {children}
    </button>
  );
}

export function IconButton({ className = "", tone = "secondary", title = "", children, ...props }) {
  return (
    <Button
      {...props}
      className={className}
      tone={tone}
      iconOnly
      title={title}
      aria-label={props["aria-label"] || title || undefined}
    >
      {children}
    </Button>
  );
}

export function SegmentedControl({
  className = "",
  options = [],
  value,
  onChange,
  ariaLabel = "Selector",
  variant = "default",
}) {
  const normalizedOptions = Array.isArray(options) ? options.filter(Boolean) : [];
  const activeIndex = normalizedOptions.findIndex((option) => option.value === value);
  const style = variant === "compact"
    ? {
      "--segment-count": Math.max(1, normalizedOptions.length),
      "--active-index": Math.max(0, activeIndex),
    }
    : undefined;

  return (
    <div
      className={cx(
        "nexus-ui-segmented",
        variant !== "default" && `nexus-ui-segmented--${variant}`,
        activeIndex >= 0 && "has-active",
        className,
      )}
      role="tablist"
      aria-label={ariaLabel}
      style={style}
    >
      {normalizedOptions.map((option) => {
        const optionValue = option.value;
        const active = optionValue === value;
        const disabled = Boolean(option.disabled);

        return (
          <button
            key={optionValue}
            type="button"
            role="tab"
            aria-selected={active}
            aria-disabled={disabled}
            disabled={disabled}
            className={cx(
              "nexus-ui-segmented__button",
              active && "is-active",
              disabled && "is-disabled",
            )}
            onClick={() => {
              if (!disabled) {
                onChange?.(optionValue);
              }
            }}
          >
            {option.icon ? <span className="nexus-ui-segmented__icon">{option.icon}</span> : null}
            <span className="nexus-ui-segmented__label">{option.label}</span>
          </button>
        );
      })}
    </div>
  );
}
